<script setup>
import { computed,ref } from 'vue';import { studio,roles,dateLabel,getRole } from '../store.js';import Chart from '../components/Chart.vue';
const role=ref(studio.state.value.preference),level=ref('校招'),examples=ref(true),length=ref(4);const records=computed(()=>studio.state.value.sessions.filter(s=>s.roleId===role.value&&s.level===level.value&&s.mainCount===Number(length.value)&&s.rubricVersion==='demo-keyword-v1'&&s.status==='completed'&&!s.focusTopic&&s.answers.length===s.questions.length&&(examples.value||!s.seeded)).sort((a,b)=>a.completedAt.localeCompare(b.completedAt)));const plans=computed(()=>studio.state.value.plans.filter(p=>p.roleId===role.value&&p.level===level.value));
</script>
<template><div class="page-heading"><div><p class="eyebrow">SMALL STEPS, REAL PROGRESS</p><h1>让进步，有迹可循。</h1><p class="muted">在同一岗位、同一阶段里，回顾每一次表达。</p></div></div><div class="filters"><label>目标岗位<select v-model="role"><option v-for="r in roles" :value="r.id" :key="r.id">{{r.title}}</option></select></label><label>求职阶段<select v-model="level"><option>校招</option><option>初级</option><option>中级</option></select></label><label>练习长度<select v-model="length"><option :value="4">完整 · 4 道主问题</option><option :value="2">轻量 · 2 道主问题</option></select></label><label class="check-label"><input type="checkbox" v-model="examples">包含预置示例</label></div><div class="two-col"><section class="card"><div class="section-heading"><h2>练习表现趋势</h2><span class="badge">{{records.length}} 次完整练习</span></div><Chart v-if="records.length" type="line" :labels="records.map(s=>dateLabel(s.completedAt))" :values="records.map(s=>s.report.overall)"/><p v-else class="empty">当前条件下暂无完整练习。完成一次面试后，这里会出现记录。</p><p class="notice">仅统计同岗位、同阶段、同长度、同规则的完整普通面试。专项再测和提前结束的会话不混入趋势；示例数据会明确标注。</p><div v-for="s in records" :key="s.id" class="list-row"><span>{{dateLabel(s.completedAt)}} · {{s.seeded?'预置示例':'本次演示'}}</span><RouterLink :to="`/interviews/${s.id}/report`">{{s.report.overall}} 分 →</RouterLink></div></section><section class="card sage"><h2>我的专项训练</h2><p class="muted">{{getRole(role).title}} · {{level}}</p><article v-for="p in plans" :key="p.id" class="list-row"><div><h3>{{p.topic}}</h3><p class="small">{{p.status==='completed'?'学习已完成':'学习中'}}{{p.retestId?' · 已创建再测':''}}</p></div><RouterLink :to="`/practice/${p.id}`" class="button secondary">继续 →</RouterLink></article><div v-if="!plans.length" class="empty"><h3>从一次复盘开始</h3><p>在报告中选择薄弱项，即可创建专项训练。</p><RouterLink to="/interviews" class="button dark">去看面试报告 →</RouterLink></div></section></div></template>
